    else:
        # Handle scalar row index
        if np.isscalar(key) and key in self.index:
            new_values = self._data.fast_2d_xs(key, copy=True)
            return Series(new_values, index=self.columns, name=key)
        # get column
        if self.columns.is_unique:
            return self._get_item_cache(key)
        else:
            return self._constructor(self._data.get(key))
